starter.css:
h3 { margin: 0 0 8px; }

#schedule .session-card {
  padding: 12px;
  margin-bottom: 16px;
  border-left: 6px solid #6d28d9;
  border-radius: 10px;
  background: #f8fafc;
}
#schedule .session-card .badge {
  display: inline-block;
  padding: 0.1em 0.6em;
  border-radius: 999px;
  background: #ede9fe;
}
.theme-sponsor .session-card {
  border-left-color: #0e7490 !important;
}
.u-hidden { display: none !important; }

solution.css:
@layer reset, tokens, layouts, components, utilities;

@layer reset {
  h3 { margin: 0 0 8px; }
}

@layer tokens {
  :root {
    --color-brand: #6d28d9;
    --card-accent: var(--color-brand);
  }
  .theme-sponsor {
    --card-accent: #0e7490;
  }
}

@layer layouts {
  .schedule {
    display: grid;
    gap: 16px;
  }
}

@layer components {
  .session-card {
    padding: 12px;
    border-inline-start: 6px solid var(--card-accent);
    border-radius: 10px;
    background: #f8fafc;

    .badge {
      display: inline-block;
      padding: 0.1em 0.6em;
      border-radius: 999px;
      background: #ede9fe;
    }
  }
}

@layer utilities {
  .u-hidden { display: none; }
}
